<script setup lang="ts">
import { ref, watch, computed, onMounted, onUnmounted } from 'vue'; import { useRoute } from 'vue-router'; import Button from 'primevue/button'; import InputText from 'primevue/inputtext'; import Select from 'primevue/select'; import Dialog from 'primevue/dialog'; import Textarea from 'primevue/textarea'; import { useToast } from 'primevue/usetoast';
import { api, currentUser, downloadCsv } from '../lib/api'; import { useQuery } from '../composables/useQuery'; import { statuses, serviceNames, date, money, type Ride, type Data } from '../lib/types'; import RideTable from '../components/RideTable.vue'; import QueryState from '../components/QueryState.vue'; import StatusBadge from '../components/StatusBadge.vue'; import OperationsMap from '../components/OperationsMap.vue';
const detailLoading = ref(false), detailError = ref(''), detailId = ref(''); let detailRevision = 0;
const route = useRoute(), toast = useToast(), search = ref(String(route.query.q ?? '')), filter = ref<string | null>(route.path === '/dispatch' ? 'ACTIVE' : null), service = ref<string | null>(null), cursor = ref<string | null>(null), page = ref(1), selected = ref<Ride>(), timeline = ref<Data[]>([]), detail = ref(false), command = ref(''), reason = ref(''), busy = ref(false), next = ref<string | null>(null); const cursorStack: (string | null)[] = [];
const { data, loading, error, refresh } = useQuery(async () => { const p = new URLSearchParams({ pageSize: '15' }); if (search.value) p.set('q', search.value); if (filter.value) p.set('status', filter.value); if (service.value) p.set('service', service.value); if (cursor.value) p.set('cursor', cursor.value); const result = await api<{ items: Ride[]; nextCursor: string | null; hasMore: boolean }>('/admin/rides?' + p); if (filter.value === 'ACTIVE') result.items = result.items.filter(r => ['SEARCHING', 'ASSIGNED', 'DRIVER_ARRIVED', 'IN_PROGRESS'].includes(r.status)); next.value = result.nextCursor; return result; }, 10000);
const driverQuery = useQuery(() => route.path === '/dispatch' ? api('/admin/drivers') : Promise.resolve({ items: [] }), 10000);
const canOperate = computed(() => !detailLoading.value && !detailError.value && ['OperationsAdmin', 'Dispatcher'].includes(currentUser.value?.role ?? ''));
let debounce: ReturnType<typeof setTimeout> | undefined;
watch([search, filter, service], () => { cursor.value = null; page.value = 1; cursorStack.length = 0; clearTimeout(debounce); debounce = setTimeout(refresh, 350); }); watch(() => route.query.q, value => { search.value = String(value ?? ''); });
async function select(ride: Ride) { await openById(ride.rideId); }
async function openById(id: string) {
  const revision = ++detailRevision;
  if (detailId.value !== id) { selected.value = undefined; timeline.value = []; command.value = ''; reason.value = ''; }
  detailId.value = id; detail.value = true; detailLoading.value = true; detailError.value = '';
  try {
    const [snapshot, events] = await Promise.all([api<Ride>('/rides/' + encodeURIComponent(id)), api('/rides/' + encodeURIComponent(id) + '/events')]);
    if (revision === detailRevision) { selected.value = snapshot; timeline.value = events.items; }
  } catch (e) { if (revision === detailRevision) detailError.value = (e as Error).message; }
  finally { if (revision === detailRevision) detailLoading.value = false; }
}
watch(() => route.query.id, id => { if (typeof id === 'string' && id) void openById(id); }, { immediate: true });
watch(detail, open => { if (!open) { detailRevision++; detailLoading.value = false; } });
async function act() { if (!selected.value || detailLoading.value || detailError.value || busy.value) return; busy.value = true; try { const path = command.value === 'cancel' ? '/rides/' + selected.value.rideId + '/cancel' : '/admin/rides/' + selected.value.rideId + '/' + command.value; const result = await api<Ride>(path, { method: 'POST', idempotent: true, body: { expectedVersion: selected.value.version, reasonCode: reason.value } }); command.value = ''; reason.value = ''; await select(result); await refresh(); toast.add({ severity: 'success', summary: 'Đã ghi nhận thao tác', life: 3000 }); } catch (e) { toast.add({ severity: 'error', summary: (e as Error).message, life: 6000 }); } finally { busy.value = false; } }
function paginate(forward: boolean) { if (loading.value || (forward ? !next.value : page.value === 1)) return; if (forward) { cursorStack.push(cursor.value); cursor.value = next.value; page.value++; } else { cursor.value = cursorStack.pop() ?? null; page.value--; } void refresh(); }
function exportRows() { downloadCsv('grap-chuyen-xe-trang-hien-tai.csv', (data.value?.items ?? []).map(r => ({ code: r.rideCode, customer: r.customer.name, service: serviceNames[r.serviceTypeCode], pickup: r.pickup.address, dropoff: r.dropoff.address, fare: r.fare.customerPayable, status: statuses[r.status]?.label, time: date(r.createdAt) })), { code: 'Mã chuyến', customer: 'Khách hàng', service: 'Dịch vụ', pickup: 'Điểm đón', dropoff: 'Điểm đến', fare: 'Cước VND', status: 'Trạng thái', time: 'Thời gian' }); }
function reload() { void refresh(); if (detail.value && selected.value) void select(selected.value); } onMounted(() => { window.addEventListener('grap:refresh', reload); }); onUnmounted(() => { detailRevision++; clearTimeout(debounce); window.removeEventListener('grap:refresh', reload); });
</script>
<template><div class="page-heading"><div><div class="eyebrow">HÀNH TRÌNH & ĐIỀU PHỐI</div><h1>{{ route.path === '/dispatch' ? 'Điều phối trực tiếp' : 'Quản lý chuyến xe' }}<span class="green-text">.</span></h1><p>Theo dõi từng hành trình, xử lý đúng thời điểm.</p></div><div class="heading-actions"><Button label="Làm mới" icon="pi pi-refresh" outlined severity="secondary" @click="refresh"/><Button label="Xuất trang hiện tại" icon="pi pi-download" :disabled="!data" @click="exportRows"/></div></div><section v-if="route.path === '/dispatch'" class="panel map-panel"><QueryState :loading="driverQuery.loading.value" :error="driverQuery.error.value" @retry="driverQuery.refresh"/><OperationsMap :drivers="driverQuery.data.value?.items ?? []"/><div class="map-footer"><span><i class="legend-dot emerald"></i>Vị trí mới</span><span><i class="legend-dot grey"></i>Ngoại tuyến / vị trí cũ</span><span class="map-footer-right">Tự cập nhật mỗi 10 giây</span></div></section><section class="panel"><div class="filter-bar"><span class="search-input"><i class="pi pi-search"></i><InputText v-model="search" placeholder="Tìm mã chuyến, tên khách hàng…" aria-label="Tìm chuyến"/></span><Select v-model="filter" :options="[{label: 'Tất cả trạng thái', value: null}, {label: 'Chuyến đang hoạt động', value: 'ACTIVE'}, ...Object.entries(statuses).filter(([k]) => ['SEARCHING','ASSIGNED','DRIVER_ARRIVED','IN_PROGRESS','COMPLETED','CANCELED','NO_DRIVER','EXPIRED'].includes(k)).map(([value,s]) => ({ value, label: s.label }))]" option-label="label" option-value="value" placeholder="Trạng thái" aria-label="Lọc trạng thái chuyến"/><Select v-model="service" aria-label="Lọc dịch vụ" :options="[{label: 'Tất cả dịch vụ', value: null}, ...Object.entries(serviceNames).map(([value,label]) => ({value,label}))]" option-label="label" option-value="value"/><Button v-if="search || service || filter !== (route.path === '/dispatch' ? 'ACTIVE' : null)" label="Xóa bộ lọc" icon="pi pi-filter-slash" text severity="secondary" @click="search='';service=null;filter=route.path==='/dispatch'?'ACTIVE':null"/><span class="filter-count">{{ data?.items.length ?? 0 }} chuyến trên trang</span></div><QueryState :loading="loading" :error="error" @retry="refresh"/><RideTable v-if="data" :rides="data.items" @select="select"/><div class="pagination"><span>Trang {{ page }} · 15 chuyến / trang</span><div><Button icon="pi pi-angle-left" severity="secondary" text :disabled="loading || page === 1" aria-label="Trang trước" @click="paginate(false)"/><Button icon="pi pi-angle-right" severity="secondary" text :disabled="loading || !next" aria-label="Trang sau" @click="paginate(true)"/></div></div></section>
<Dialog v-model:visible="detail" modal header="Chi tiết hành trình" :style="{width:'720px'}" :breakpoints="{'768px':'95vw'}"><QueryState :loading="detailLoading" :error="detailError" @retry="openById(detailId)"/><template v-if="selected"><div class="detail-title"><div><span class="eyebrow">{{ selected.rideCode }}</span><h2>{{ serviceNames[selected.serviceTypeCode] }}</h2></div><StatusBadge :status="selected.status"/></div><OperationsMap :pickup="selected.pickup" :dropoff="selected.dropoff" compact/><div class="detail-grid"><div><span>Khách hàng</span><strong>{{ selected.customer.name }}</strong><small>{{ selected.customer.phone }}</small></div><div><span>Tài xế</span><strong>{{ selected.driver?.name ?? 'Chưa được phân công' }}</strong><small>{{ selected.driver?.plate ?? 'Đang chờ ghép chuyến' }}</small></div><div><span>Khởi tạo</span><strong>{{ date(selected.createdAt) }}</strong></div><div><span>Thanh toán</span><strong>Tiền mặt · {{ money(selected.fare.customerPayable) }}</strong><StatusBadge v-if="selected.payment" :status="selected.payment.status"/></div></div><div class="fare-breakdown"><div><span>Giá mở cửa</span><b>{{ money(selected.fare.baseFare) }}</b></div><div><span>Cước quãng đường</span><b>{{ money(selected.fare.distanceFare) }}</b></div><div><span>Cước thời gian</span><b>{{ money(selected.fare.durationFare) }}</b></div><div><span>Phí dịch vụ</span><b>{{ money(selected.fare.serviceFee) }}</b></div><div class="total"><span>Khách cần thanh toán</span><b>{{ money(selected.fare.customerPayable) }}</b></div></div><h3>Nhật ký hành trình</h3><div class="timeline"><div v-for="event in timeline" :key="event.id" class="timeline-item"><span class="timeline-dot"></span><div><strong>{{ event.eventType }}</strong><p v-if="event.reason">{{ event.reason }}</p><small>{{ date(event.createdAt) }} · Phiên bản {{ event.sequence }}</small></div></div></div><div v-if="canOperate && ['SEARCHING','ASSIGNED','DRIVER_ARRIVED'].includes(selected.status)" class="detail-actions"><Button v-if="selected.driver" label="Điều phối lại" icon="pi pi-sync" outlined @click="command='reassignment-requests'"/><Button label="Hủy theo yêu cầu hỗ trợ" severity="danger" outlined @click="command='cancel'"/></div><Button v-if="canOperate && currentUser?.role === 'OperationsAdmin' && selected.status === 'IN_PROGRESS'" label="Kết thúc sớm có lý do" severity="danger" outlined @click="command='end-early'"/></template></Dialog><Dialog :visible="!!command" @update:visible="value => { if (!value) command = '' }" modal header="Xác nhận thao tác vận hành" :style="{width:'460px'}"><p class="muted">Thao tác áp dụng trên phiên bản hiện tại của chuyến và được ghi audit.</p><label>Lý do xử lý<Textarea v-model="reason" rows="4" class="full-width" placeholder="Nhập lý do cụ thể (bắt buộc)"/></label><template #footer><Button label="Quay lại" text severity="secondary" @click="command=''"/><Button label="Xác nhận" :disabled="reason.trim().length < 3" :loading="busy" @click="act"/></template></Dialog></template>
